public final class GlRenderState {
    private GlRenderState() {
    }

    public static Snapshot capture() {
        return new Snapshot(GL11.glIsEnabled((int)2884), GL11.glIsEnabled((int)3042), GL11.glIsEnabled((int)2929), GL11.glGetBoolean((int)2930));
    }

    public static void restore(Snapshot state) {
        if (state == null) {
            return;
        }
        if (state.cullEnabled) {
            RenderSystem.enableCull();
        } else {
            RenderSystem.disableCull();
        }
        if (state.blendEnabled) {
            RenderSystem.enableBlend();
        } else {
            RenderSystem.disableBlend();
        }
        if (state.depthTestEnabled) {
            RenderSystem.enableDepthTest();
        } else {
            RenderSystem.disableDepthTest();
        }
        RenderSystem.depthMask((boolean)state.depthMaskEnabled);
    }

    public static int packNormal(float x, float y, float z) {
        float len = (float)Math.sqrt(x * x + y * y + z * z);
        if (len > 1.0E-6f && !Float.isNaN(len)) {
            x /= len;
            y /= len;
            z /= len;
        }
        int xi = Math.max(-511, Math.min(511, Math.round(x * 511.0f)));
        int yi = Math.max(-511, Math.min(511, Math.round(y * 511.0f)));
        int zi = Math.max(-511, Math.min(511, Math.round(z * 511.0f)));
        return xi & 0x3FF | (yi & 0x3FF) << 10 | (zi & 0x3FF) << 20;
    }

