package com.ysmef.geomodel.renderer;

import com.ysmef.geomodel.YSMGeoCompat;
import com.ysmef.geomodel.cpu.YsmCpuRenderPath;
import com.ysmef.geomodel.cpu.YsmCpuSkinShader;
import com.ysmef.geomodel.gpu.YsmBoneSkinShader;
import com.ysmef.geomodel.gpu.YsmGpuRenderPath;
import com.ysmef.geomodel.model.RenderBridgeRegistry;

public final class RenderPaths {
    private RenderPaths() {
    }

    public static void init() {
        boolean cpu;
        YsmGpuRenderPath.warmUp();
        YsmCpuRenderPath.warmUp();
        boolean gpu = RenderBridgeRegistry.gpu() != null;
        boolean bl = cpu = RenderBridgeRegistry.cpu() != null;
        if (!gpu || !cpu) {
            YSMGeoCompat.LOGGER.error("YSM-GEO Compat: direct draw path registration incomplete (gpu={}, cpu={}); converted meshes will fall back to Epic Fight's compute path", (Object)gpu, (Object)cpu);
        } else {
            YSMGeoCompat.LOGGER.info("YSM-GEO Compat: direct draw paths registered (gpu=true, cpu=true)");
        }
        try {
            boolean boneOk = YsmBoneSkinShader.ensureCompiled();
            boolean cpuOk = YsmCpuSkinShader.ensureCompiled();
            YSMGeoCompat.LOGGER.info("YSM-GEO Compat: skinning shaders precompiled (gpuPath={}, cpuPath={})", (Object)boneOk, (Object)cpuOk);
        }
        catch (Throwable t) {
            YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: skinning shader precompilation failed; the paths will retry on first draw", t);
        }
    }
}

