import java.lang.reflect.Method;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import yesman.epicfight.world.capabilities.EpicFightCapabilities;
import yesman.epicfight.world.capabilities.entitypatch.LivingEntityPatch;

public final class YSMBattleMode {
    private static final Map<Class<?>, Method> FIGHT_MODE_METHODS = new ConcurrentHashMap();
    private static final Method NO_FIGHT_MODE = YSMBattleMode.NO_FIGHT_MODE_MARKER();
    private static boolean fightModeLookupFailed = false;

    private YSMBattleMode() {
    }

    public static boolean isBattleMode(LivingEntity entity) {
        if (entity == null) {
            return false;
        }
        LivingEntityPatch patch = (LivingEntityPatch)EpicFightCapabilities.getEntityPatch((Entity)entity, LivingEntityPatch.class);
        if (patch == null) {
            return false;
        }
        Method method = FIGHT_MODE_METHODS.computeIfAbsent(patch.getClass(), YSMBattleMode::findFightModeMethod);
        if (method == NO_FIGHT_MODE) {
            return false;
        }
        try {
            return (Boolean)method.invoke((Object)patch, new Object[0]);
        }
        catch (Exception e) {
            if (!fightModeLookupFailed) {
                fightModeLookupFailed = true;
                YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: failed to query isFightMode on {}", (Object)patch.getClass().getName(), (Object)e);
            }
            return false;
        }
    }

    private static Method findFightModeMethod(Class<?> patchClass) {
        try {
            return patchClass.getMethod("isFightMode", new Class[0]);
        }
        catch (NoSuchMethodException e) {
            return NO_FIGHT_MODE;
        }
    }

    private static Method NO_FIGHT_MODE_MARKER() {
        try {
            return YSMBattleMode.class.getDeclaredMethod("noFightModeMarker", new Class[0]);
        }
        catch (NoSuchMethodException e) {
            throw new IllegalStateException(e);
        }
    }

    private static void noFightModeMarker() {
    }
}

