package com.ysmef.geomodel.renderer;

import com.ysmef.geomodel.YSMGeoCompat;
import com.ysmef.geomodel.model.YSMMesh;
import com.ysmef.geomodel.model.YSMMeshLibrary;
import com.ysmef.geomodel.model.runtime.YSMRuntimeBridge;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.LivingEntity;
import yesman.epicfight.api.asset.AssetAccessor;
import yesman.epicfight.api.client.model.Meshes;
import yesman.epicfight.client.mesh.HumanoidMesh;

public final class YSMMeshSelector {
    private static final Map<UUID, String[]> LOGGED_MESH_USE = new ConcurrentHashMap<UUID, String[]>();

    private YSMMeshSelector() {
    }

    public static void clear() {
        LOGGED_MESH_USE.clear();
    }

    public static AssetAccessor<HumanoidMesh> selectResolvedMesh(LivingEntity entity, Meshes.MeshAccessor<YSMMesh> accessor, String modelId, ResourceLocation texture, String textureName, String displayName) {
        if (entity == null || accessor == null) {
            return null;
        }
        try {
            YSMMesh mesh = (YSMMesh)accessor.get();
            YSMMeshLibrary.markMeshLoaded(modelId);
            mesh.setRuntimeModelId(modelId);
            YSMRuntimeBridge.setCurrentEntity(entity);
            if (texture != null) {
                YSMMeshLibrary.ensureTextureUploaded(texture);
                mesh.setTextureOverride(texture);
            }
            YSMMeshSelector.logMeshUsedOnce(entity, modelId, textureName, texture, displayName);
        }
        catch (Throwable t) {
            YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: failed to load generated mesh for '{}', falling back to Epic Fight default mesh", (Object)modelId, (Object)t);
            return null;
        }
        Meshes.MeshAccessor<YSMMesh> result = accessor;
        return result;
    }

    private static void logMeshUsedOnce(LivingEntity entity, String modelId, String textureName, ResourceLocation texture, String displayName) {
        String[] prev = LOGGED_MESH_USE.get(entity.m_20148_());
        if (prev != null && prev[0].equals(modelId) && Objects.equals(prev[1], textureName)) {
            return;
        }
        LOGGED_MESH_USE.put(entity.m_20148_(), new String[]{modelId, textureName});
        YSMGeoCompat.LOGGER.info("YSM-GEO Compat: rendering '{}' with converted TLM base mesh (model='{}', texture='{}' -> {})", (Object)displayName, (Object)modelId, (Object)textureName, (Object)texture);
    }
}

