@Mod(value="ysm_geo_compat")
public class YSMGeoCompat {
    public static final String MODID = "ysm_geo_compat";
    public static final Logger LOGGER = LogManager.getLogger((String)"YSM-GEO Compat");

    public YSMGeoCompat() {
        YSMCompatConfig.register();
        YSMGeoCompat.installMolangErrorReporter();
        LOGGER.info("YSM-GEO Compat: Initialized successfully");
